import{_ as e,o as s,c as i,a4 as d}from"./chunks/framework.BMj-uaUw.js";const k=JSON.parse('{"title":"单元 10 课后练习","description":"","frontmatter":{},"headers":[{"level":2,"title":"必做题","slug":"必做题","link":"#必做题","children":[{"level":3,"title":"练习 1 · 活动列表状态模块","slug":"练习-1-·-活动列表状态模块","link":"#练习-1-·-活动列表状态模块","children":[]},{"level":3,"title":"练习 2 · 请求层封装","slug":"练习-2-·-请求层封装","link":"#练习-2-·-请求层封装","children":[]},{"level":3,"title":"练习 3 · 列表页接真实接口，补齐四态","slug":"练习-3-·-列表页接真实接口-补齐四态","link":"#练习-3-·-列表页接真实接口-补齐四态","children":[]}]},{"level":2,"title":"选做题","slug":"选做题","link":"#选做题","children":[{"level":3,"title":"练习 4 · 请求竞态防护","slug":"练习-4-·-请求竞态防护","link":"#练习-4-·-请求竞态防护","children":[]}]},{"level":2,"title":"自检标准","slug":"自检标准","link":"#自检标准","children":[]},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题","children":[]},{"level":2,"title":"交作业前","slug":"交作业前","link":"#交作业前","children":[]}],"relativePath":"unit10/practice.md","filePath":"unit10/practice.md","lastUpdated":1789307994000}'),a={name:"unit10/practice.md"};function o(r,t,l,n,c,h){return s(),i("div",null,[...t[0]||(t[0]=[d(`<h1 id="单元-10-课后练习" tabindex="-1">单元 10 课后练习 <a class="header-anchor" href="#单元-10-课后练习" aria-label="Permalink to &quot;单元 10 课后练习&quot;">​</a></h1><p>本单元的练习都是&quot;能直接进项目&quot;的产出。<strong>三道必做题，一道选做题。</strong></p><p>必做题做完，你的项目会多出两个新目录：<code>src/stores/</code> 里的两个状态模块、 <code>src/api/</code> 里的请求层。这三道题合起来正好是第 10 周阶段性任务的全部内容 —— <strong>把路由与状态接起来，跑通完整的鉴权链路</strong>。</p><p>各小节末尾还有针对性的小练习，那些帮助理解单点；这一页的练习是单元级的产出， 作为过程性考核的依据。</p><h2 id="必做题" tabindex="-1">必做题 <a class="header-anchor" href="#必做题" aria-label="Permalink to &quot;必做题&quot;">​</a></h2><h3 id="练习-1-·-活动列表状态模块" tabindex="-1">练习 1 · 活动列表状态模块 <a class="header-anchor" href="#练习-1-·-活动列表状态模块" aria-label="Permalink to &quot;练习 1 · 活动列表状态模块&quot;">​</a></h3><p>按 <a href="/frontend-engineering-course/unit10/02-pinia-basics.html#实战活动列表的状态模块">10.2 的实战</a>， 写出 <code>src/stores/activity.js</code>，并加上持久化。</p><p><strong>要求</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>筛选条件</td><td>关键词、状态、分页（页码 + 每页条数）都在 store 里，不放组件</td></tr><tr><td>派生值</td><td>至少两个：是否空数据、总页数</td></tr><tr><td>持久化</td><td>筛选条件与每页条数持久化，<strong>页码不持久化</strong></td></tr><tr><td>刷新行为</td><td>刷新页面后，关键词与状态还在，页码回到第一页</td></tr><tr><td>动作</td><td>取列表、改筛选条件（自动回第一页）、重置筛选</td></tr></tbody></table><p><strong>提交形式</strong>：<code>src/stores/activity.js</code> 与改造后的 <code>ActivityListView.vue</code>。</p><p><strong>验收标准</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>数据位置</td><td>组件里搜不到 <code>ref</code> 定义的筛选字段，它们都在 store 里</td></tr><tr><td>持久化字段</td><td><code>localStorage</code> 里只有筛选条件相关字段，没有 <code>loading</code>、<code>error</code></td></tr><tr><td>响应性</td><td>组件用 <code>storeToRefs</code> 解构状态，改筛选条件页面立刻响应</td></tr><tr><td>刷新验证</td><td>手动验证：筛出&quot;报名中&quot; → 刷新 → 仍然是&quot;报名中&quot;、第一页</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">常见的两种不合格</p><ol><li><strong>页码也持久化了</strong>。用户从第一页切到第五页，刷新后停在第五页， 但数据可能已经变了，这一页是空的 —— 用户会以为&quot;活动都没了&quot;。</li><li><strong>直接解构丢响应性</strong>。<code>const { filters } = useActivityStore()</code>， 改筛选条件页面不更新，要手动刷新才看到。</li></ol></div><h3 id="练习-2-·-请求层封装" tabindex="-1">练习 2 · 请求层封装 <a class="header-anchor" href="#练习-2-·-请求层封装" aria-label="Permalink to &quot;练习 2 · 请求层封装&quot;">​</a></h3><p>按 <a href="/frontend-engineering-course/unit10/04-request-layer.html">10.4</a> 写出完整的请求层。</p><p><strong>要求</strong></p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>src/api/request.js</code></td><td>axios 实例（基础地址从环境变量读 + 超时）、请求拦截器注入 token、响应拦截器剥数据判业务码</td></tr><tr><td><code>src/api/auth.js</code></td><td>登录、退出、取当前用户</td></tr><tr><td><code>src/api/activity.js</code></td><td>活动列表、详情、新建、编辑、删除</td></tr><tr><td><code>src/api/signup.js</code></td><td>报名列表、通过、拒绝（带理由）</td></tr></tbody></table><p><strong>401 处理的具体要求</strong></p><ul><li>清空登录态（走 store，不要直接 <code>localStorage.removeItem</code>）。</li><li>用 <code>router.push</code> 跳登录页，<strong>带 <code>redirect</code> 参数</strong>记住原地址。</li><li>并发的多个 <code>401</code> <strong>只跳转一次</strong>，只提示一次。</li><li>不允许出现 <code>window.location.href</code>。</li></ul><p><strong>验收标准</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>地址集中</td><td>全项目搜 <code>http://</code>，只在 <code>.env</code> 文件里出现</td></tr><tr><td>无裸 axios</td><td>组件与 store 里搜 <code>axios</code>，搜不到（<code>api/</code> 除外）</td></tr><tr><td>一接口一函数</td><td>每个接口有独立的、名字表达业务含义的函数</td></tr><tr><td>401 验证</td><td>手动把 token 改坏，访问任意页面，能正确跳登录页并记住原地址</td></tr></tbody></table><details class="details custom-block"><summary>怎么手动验证 401 不无限跳转</summary><ol><li>登录后，在浏览器控制台执行 <code>localStorage.clear()</code>（或改成插件用的 key）。</li><li>在活动列表页点&quot;刷新&quot;。</li><li>观察：页面跳到了登录页，<strong>只跳一次</strong>，控制台没有十几条&quot;跳转&quot;日志。</li></ol><p>如果出现反复跳转，检查拦截器里有没有做&quot;正在跳转&quot;的标记。</p></details><h3 id="练习-3-·-列表页接真实接口-补齐四态" tabindex="-1">练习 3 · 列表页接真实接口，补齐四态 <a class="header-anchor" href="#练习-3-·-列表页接真实接口-补齐四态" aria-label="Permalink to &quot;练习 3 · 列表页接真实接口，补齐四态&quot;">​</a></h3><p>把上一单元的活动列表页从&quot;写死的数据&quot;改成&quot;从接口取数据&quot;， 按<a href="/frontend-engineering-course/unit10/06-case-fetch.html">案例 04</a> 的四态模板实现。</p><p><strong>四态的验收内容</strong></p><table tabindex="0"><thead><tr><th>状态</th><th>怎么触发</th><th>页面应该显示</th></tr></thead><tbody><tr><td>加载中</td><td>正常请求发出后</td><td>转圈或&quot;正在加载&quot;，不能同时显示&quot;没有活动&quot;</td></tr><tr><td>出错</td><td>mock 里返回 <code>code</code> 非 <code>200</code>，或断开网络</td><td>错误说明 + 重试按钮，<strong>重试按钮真的能用</strong></td></tr><tr><td>空数据</td><td>筛选一个没有结果的条件下</td><td>&quot;还没有活动&quot; + 一个可点的动作</td></tr><tr><td>有数据</td><td>正常情况</td><td>列表，<code>v-for</code> 用业务 id 作 key</td></tr></tbody></table><p><strong>验收标准</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>四态齐全</td><td>四种状态都能手动触发出来，截图留证</td></tr><tr><td>顺序正确</td><td>加载中时不闪&quot;没有活动&quot;；出错时不显示&quot;没有活动&quot;</td></tr><tr><td>错误提示一次</td><td>出错时全局只弹一条提示，页面错误态与 toast 不重复</td></tr><tr><td>重试可用</td><td>点重试按钮能重新发起请求，成功后有数据</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">用 mock 主动制造错误</p><p>在 mock 里加一个开关，方便演示三种错误：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (query.mode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;error&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { code: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, message: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;服务器开小差了&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, data: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (query.mode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;empty&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { code: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, message: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;success&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, data: { list: [], total: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这样你不用真去断网，就能把四态一个个演示出来。</p></div><h2 id="选做题" tabindex="-1">选做题 <a class="header-anchor" href="#选做题" aria-label="Permalink to &quot;选做题&quot;">​</a></h2><h3 id="练习-4-·-请求竞态防护" tabindex="-1">练习 4 · 请求竞态防护 <a class="header-anchor" href="#练习-4-·-请求竞态防护" aria-label="Permalink to &quot;练习 4 · 请求竞态防护&quot;">​</a></h3><p>给活动列表页加上竞态防护，用&quot;加 3 秒延迟的慢接口&quot;验证快速切页不会串数据。</p><p><strong>做两遍，对比两种方案</strong></p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>观察什么</th></tr></thead><tbody><tr><td>序号标记</td><td>每次请求领一个自增号，回来时比对</td><td>网络面板里旧请求仍然走完，只是结果被丢弃</td></tr><tr><td><code>AbortController</code></td><td>新请求发出前取消旧请求</td><td>网络面板里旧请求显示为 <code>canceled</code></td></tr></tbody></table><p><strong>验收标准</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>能复现 bug</td><td>先不加防护，用慢接口复现出&quot;点了第二页显示第一页数据&quot;</td></tr><tr><td>修好了</td><td>加上防护后，快速连点三页，最终显示的一定是最后点的那一页</td></tr><tr><td>有对比记录</td><td>写下两种方案的差异，至少三条</td></tr><tr><td>边界情况</td><td>加载态不会卡住，取消的请求不弹错误提示</td></tr></tbody></table><details class="details custom-block"><summary>怎么造出&quot;后发先至&quot;</summary><p>在 mock 里让延迟由参数决定：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> delay</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(query.delay) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> setTimeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(resolve, delay))</span></span></code></pre></div><p>请求时第一个用 <code>delay=3000</code>，第二个用 <code>delay=300</code>。 第一次请求在 3 秒后才回来，第二次在 0.3 秒就回来了 —— 后发先至，竞态必现。 <strong>把 3 秒那次请求的结果丢弃或取消掉，才算修好。</strong></p></details><div class="warning custom-block"><p class="custom-block-title">别用 <code>setTimeout</code> 假装慢接口就以为修好了</p><p>如果防护代码里判断错了 <code>aborted</code> 的时机，页面可能只是&quot;恰好&quot;显示对了。 <strong>多用几组延迟组合试</strong>：3000 配 300、3000 配 3000、500 配 2000， 三种都要保证最终显示正确。</p></div><h2 id="自检标准" tabindex="-1">自检标准 <a class="header-anchor" href="#自检标准" aria-label="Permalink to &quot;自检标准&quot;">​</a></h2><p>做完本单元练习后，逐条自查：</p><ul><li>[ ] 能说出一份数据该放组件内部、props、provide/inject 还是 Pinia 的判断依据</li><li>[ ] 项目里有一个完整的登录态模块，包含 token、用户信息、登录、退出</li><li>[ ] 登录态模块只持久化该持久化的字段，刷新后能自动恢复</li><li>[ ] 退出登录时，内存状态与 <code>localStorage</code> 都被清干净</li><li>[ ] 有一个统一的请求层，基础地址从环境变量读</li><li>[ ] 请求拦截器会自动注入 token，页面里不用手写</li><li>[ ] 响应拦截器会剥数据、判业务码、统一提示错误</li><li>[ ] <code>401</code> 用 router 跳转并记住原地址，且不会无限跳转</li><li>[ ] 项目里搜不到散落的接口地址，<code>api/</code> 之外没有裸 <code>axios</code></li><li>[ ] 活动列表页四态齐全，出错有可用的重试入口</li><li>[ ] 组件用 <code>storeToRefs</code> 解构状态，改数据页面能立刻响应</li><li>[ ] 第 10 周链路验证过一遍：未登录被拦 → 登录后回原地址 → 退出后再次被拦</li></ul><p>全部打勾，这个单元过关。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><details class="details custom-block"><summary>我的接口地址是别人的电脑，同学访问不到怎么办</summary><p>接口地址不要写死成 <code>http://192.168.1.x</code>。两种做法：</p><ol><li><strong>用 mock</strong>：<code>vite-plugin-mock</code> 在本地起接口，不依赖任何人。</li><li><strong>用代理</strong>：在 <code>vite.config.js</code> 里配 <code>server.proxy</code>， 把 <code>/api</code> 转发到后端地址。这样接口地址在代码里始终是 <code>/api</code>。</li></ol><p><strong>验收时用 mock 的项目一样算过关</strong> —— 重点是请求层的结构与错误处理， 不是&quot;有没有真后端&quot;。</p></details><details class="details custom-block"><summary>用 <code>pinia-plugin-persistedstate</code> 时 <code>paths</code> 报错</summary><p><code>paths</code> 是旧版（v3 及更早）的配置名，新版（v4 起）改名叫 <code>pick</code>。 先确认装的版本：<code>pnpm list pinia-plugin-persistedstate</code>， 然后按版本用对应的名字。<strong>本课程以 <code>pick</code> 为准。</strong></p></details><details class="details custom-block"><summary><code>storeToRefs</code> 解构出来的方法调用不了</summary><p><code>storeToRefs</code> 只处理状态（<code>ref</code>、<code>computed</code>），<strong>方法会被跳过</strong>， 所以解构不到方法不是 bug。正确做法是方法直接用 store 调： <code>authStore.logout()</code>。</p></details><details class="details custom-block"><summary>刷新后登录态没了，但我明明配了持久化</summary><p>按顺序排查：</p><ol><li>插件注册了吗？<code>pinia.use(piniaPluginPersistedstate)</code> 在 <code>main.js</code> 里有没有。</li><li><code>persist</code> 配置写在哪？组合式写法是 <code>defineStore</code> 的<strong>第三个参数</strong>， 不是 <code>return</code> 里。</li><li><code>localStorage</code> 里有没有对应的 key？打开开发者工具 → Application → Local Storage 看一眼。</li><li>状态是不是通过 store 改的？如果直接改了别的副本，<code>watch</code> 不会触发。</li></ol></details><details class="details custom-block"><summary>为什么 <code>localStorage</code> 里存的是 <code>&quot;[object Object]&quot;</code></summary><p>写入时忘了 <code>JSON.stringify</code>。用插件不会遇到这个问题（它内部处理了序列化）； 手写持久化时读写要成对：写 <code>JSON.stringify</code>，读 <code>JSON.parse</code>。</p></details><h2 id="交作业前" tabindex="-1">交作业前 <a class="header-anchor" href="#交作业前" aria-label="Permalink to &quot;交作业前&quot;">​</a></h2><p>按 <a href="/frontend-engineering-course/unit12/04-delivery.html">12.4 的交付要求</a> 整理，本单元要提交：</p><table tabindex="0"><thead><tr><th>材料</th><th>位置</th><th>说明</th></tr></thead><tbody><tr><td>状态模块</td><td><code>src/stores/</code></td><td>至少两个：<code>auth.js</code>、<code>activity.js</code></td></tr><tr><td>请求层</td><td><code>src/api/</code></td><td><code>request.js</code> 加至少两个业务接口文件</td></tr><tr><td>页面改造</td><td><code>src/views/</code></td><td>活动列表页四态齐全</td></tr><tr><td>实验记录</td><td><code>docs/unit10-notes.md</code></td><td>四态截图、竞态复现与修复过程、两种方案对比</td></tr></tbody></table><p><strong>实验记录比代码更能体现你的理解</strong> —— 把自己&quot;先复现出 bug、再修好&quot;的过程写下来，比只交一份正确代码更有价值。</p><hr><p>上一节：<a href="/frontend-engineering-course/unit10/06-case-fetch.html">案例 04 · 从接口获取数据</a> · 下一单元：<a href="/frontend-engineering-course/unit11/">单元 11 · 项目启动与核心业务</a></p>`,54)])])}const u=e(a,[["render",o]]);export{k as __pageData,u as default};
